/** Auto-generated DFW metro city outlines (NCTCOG Cities, equirectangular). */
export const DFW_MAP_VIEWBOX = "0 0 975 700";
export const DFW_MAP_SIZE = { width: 975, height: 700 } as const;

/** Geographic bounds used by `projectDFW` (lng/lat). */
export const DFW_BOUNDS = {
  lng0: -97.55,
  lng1: -96.35,
  lat0: 32.52,
  lat1: 33.38,
} as const;

export type DfwCityPath = {
  id: string;
  name: string;
  d: string;
  labelX: number;
  labelY: number;
};

/**
 * Equirectangular projection into the DFW metro viewBox.
 * Returns null outside the metro bounds.
 */
export function projectDFW(lng: number, lat: number): { x: number; y: number } | null {
  const { lng0, lng1, lat0, lat1 } = DFW_BOUNDS;
  if (lng < lng0 || lng > lng1 || lat < lat0 || lat > lat1) return null;
  const x = ((lng - lng0) / (lng1 - lng0)) * DFW_MAP_SIZE.width;
  const y = ((lat1 - lat) / (lat1 - lat0)) * DFW_MAP_SIZE.height;
  return { x, y };
}

export function isInDFW(lng: number, lat: number): boolean {
  const { lng0, lng1, lat0, lat1 } = DFW_BOUNDS;
  return lng >= lng0 && lng <= lng1 && lat >= lat0 && lat <= lat1;
}

